package com.realstant.nativegame; public final class PhysicsEngine { public void update(PhysicsState s,InputState in,float dt,VehicleSpec v){float throttle=in.gas?1f:0f; float brake=in.brake?1f:0f; float accel=(v.power/1000f)*28f*throttle-(v.brake/1000f)*34f*brake-0.7f*s.speed; s.speed+=accel*dt; if(s.speed<0)s.speed=0;if(s.speed>GameConfig.MAX_SPEED)s.speed=GameConfig.MAX_SPEED; float turn=(in.left?-1:0)+(in.right?1:0); s.steer+=(turn-s.steer)*Math.min(1f,dt*7f); s.heading+=s.steer*(0.42f+0.018f*s.speed)*dt; s.x+=(float)Math.sin(s.heading)*s.speed*dt; s.z+=(float)Math.cos(s.heading)*s.speed*dt; s.fuel-=throttle*dt*0.08f; if(s.fuel<0)s.fuel=0;} }
